	private void assertOptionalFanout(Tier tier) {
		System.setProperty("rdf4j.lmdb.janinoCodegen.enabled", Boolean.toString(tier == Tier.COMPILED));
		OptionalFanoutRouteAccess.resetIrKernelMetrics();
		LmdbNativeExpressionCompiler.LAZY_VALUE_CALLS.set(0L);

		Map<List<String>, Integer> actual = new HashMap<>();
		List<Value> strongValues = new ArrayList<>();
		List<Set<String>> distinctByColumn = new ArrayList<>(OptionalFanoutFixture.BINDINGS.length);
		for (int i = 0; i < OptionalFanoutFixture.BINDINGS.length; i++) {
			distinctByColumn.add(new HashSet<>());
		}
		long[] consecutiveBaselineByColumn = new long[OptionalFanoutFixture.BINDINGS.length];
		String[] previousValues = new String[OptionalFanoutFixture.BINDINGS.length];
		var previous = SlowQueryContextHolder.set(query, Query.QueryType.TUPLE, tier.route);
		try (SailConnection connection = repository.getSail().getConnection()) {
			var parsed = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null);
			try (var results = connection.evaluate(parsed.getTupleExpr(), null, EmptyBindingSet.getInstance(), false)) {
				while (results.hasNext()) {
					BindingSet bindingSet = results.next();
					assertThat(bindingSet).isInstanceOf(NativeProjectedBindingSet.class);
					assertThat(bindingSet.size()).isEqualTo(OptionalFanoutFixture.BINDINGS.length);
					List<String> row = new ArrayList<>(OptionalFanoutFixture.BINDINGS.length);
					for (int column = 0; column < OptionalFanoutFixture.BINDINGS.length; column++) {
						Value value = bindingSet.getValue(OptionalFanoutFixture.BINDINGS[column]);
						assertThat(value).as("fixture column %s is bound", OptionalFanoutFixture.BINDINGS[column])
								.isNotNull();
						String valueText = value.stringValue();
						if (!valueText.equals(previousValues[column])) {
							consecutiveBaselineByColumn[column]++;
						}
						previousValues[column] = valueText;
						distinctByColumn.get(column).add(valueText);
						strongValues.add(value);
						row.add(valueText);
					}
					actual.merge(List.copyOf(row), 1, Integer::sum);
				}
			}
		} finally {
			SlowQueryContextHolder.restore(previous);
		}

		long rows = actual.values().stream().mapToLong(Integer::longValue).sum();
		long consecutiveBaseline = Arrays.stream(consecutiveBaselineByColumn).sum();
		long lazyValueCalls = LmdbNativeExpressionCompiler.LAZY_VALUE_CALLS.get();
		assertThat(OptionalFanoutRouteAccess.openedIrKernels()).isPositive();
		if (tier == Tier.COMPILED) {
			assertThat(OptionalFanoutRouteAccess.compiledIrBinds()).isPositive();
			assertThat(OptionalFanoutRouteAccess.interpretedIrBinds()).isZero();
		} else {
			assertThat(OptionalFanoutRouteAccess.interpretedIrBinds()).isPositive();
			assertThat(OptionalFanoutRouteAccess.compiledIrBinds()).isZero();
		}
		assertThat(rows).as("the 1x1 fan-out fixture yields more than one 1024-row result fill")
				.isEqualTo(EXPECTED_ROWS)
				.isGreaterThan(1_024L);
		assertThat(strongValues).as("all resolved projected values remain strongly reachable during measurement")
				.hasSize(Math.toIntExact(EXPECTED_ROWS * OptionalFanoutFixture.BINDINGS.length));
		assertThat(distinctByColumn.stream().mapToInt(Set::size).toArray())
				.as("actual distinct lexical values by projected column; repeated language literals are separate source cells")
				.containsExactly(EXPECTED_DISTINCT_VALUES_BY_COLUMN);
		assertThat(actual).as("the full OPTIONAL fan-out multiset is preserved")
				.containsExactlyInAnyOrderEntriesOf(expectedRows());
		System.out.printf("OptionalFanout factor-coordinate observation: tier=%s rows=%d totalSourceResolutions=%d "
				+ "consecutiveSlotBaseline=%d baselineByColumn=%s distinctLexicalByColumn=%s%n", tier, rows,
				lazyValueCalls, consecutiveBaseline, Arrays.toString(consecutiveBaselineByColumn),
				distinctByColumn.stream().mapToInt(Set::size).toArray());
		assertThat(lazyValueCalls)
				.as("the 1x1 fixture has 49 original projected source cells: 3 prefix, 3 diagnoses, 6 severity, "
						+ "4 drugs, 8 routes, 16 route-language pairs, 3 procedures, 2 authors, 2 departments, "
						+ "and 2 statuses; tier=%s", tier)
				.isEqualTo(49L)
				.as("factor coordinates reduce source resolution below the measured consecutive-slot baseline; "
						+ "tier=%s calls=%s baseline=%s byColumn=%s distinctByColumn=%s",
						tier, lazyValueCalls, consecutiveBaseline,
						Arrays.toString(consecutiveBaselineByColumn),
						distinctByColumn.stream().mapToInt(Set::size).toArray())
				.isLessThan(consecutiveBaseline);

		NativeResultCoordinateObservation.Result observation = observeActualProducerCoordinates(tier);
		assertThat(observation.route()).isEqualTo(tier.route);
		assertThat(observation.rows()).isEqualTo(EXPECTED_ROWS);
		assertThat(observation.retainedValues())
				.as("observation keeps resolved values strongly reachable while coordinate observations are checked")
				.hasSize(Math.toIntExact(EXPECTED_ROWS * OptionalFanoutFixture.BINDINGS.length));
		assertThat(observation.totalCalls())
				.as("the output-only observation must agree with the untouched end-to-end source-resolution count")
				.isEqualTo(lazyValueCalls);
		assertThat(observation.totalCalls()).isEqualTo(49L);
		assertThat(observation.coordinateMaskCounts().values().stream().mapToLong(Long::longValue).sum())
				.isEqualTo(EXPECTED_ROWS);
		assertThat(observation.coordinateMaskCounts())
				.as("the live producer coordinates are available for exactly the nine replayed OPTIONAL outputs")
				.containsExactlyEntriesOf(Map.of(0xFF8L, EXPECTED_ROWS));
		assertThat(observation.positionMasks()).containsOnlyKeys(OptionalFanoutFixture.BINDINGS);
		assertThat(observation.positionMasks()).containsExactlyInAnyOrderEntriesOf(Map.ofEntries(
				Map.entry("patient", ValuePosition.SUBJECT),
				Map.entry("measurement", ValuePosition.SUBJECT | ValuePosition.OBJECT),
				Map.entry("reading", ValuePosition.SUBJECT | ValuePosition.OBJECT),
				Map.entry("diagnosis", ValuePosition.SUBJECT | ValuePosition.OBJECT),
				Map.entry("severity", ValuePosition.OBJECT),
				Map.entry("drug", ValuePosition.SUBJECT | ValuePosition.OBJECT),
				Map.entry("route", ValuePosition.SUBJECT | ValuePosition.OBJECT),
				Map.entry("language", ValuePosition.OBJECT),
				Map.entry("procedure", ValuePosition.SUBJECT | ValuePosition.OBJECT),
				Map.entry("author", ValuePosition.SUBJECT | ValuePosition.OBJECT),
				Map.entry("department", ValuePosition.SUBJECT | ValuePosition.OBJECT),
				Map.entry("status", ValuePosition.SUBJECT | ValuePosition.OBJECT)));

		Map<String, Integer> cellsByName = new TreeMap<>();
		Map<String, Integer> distinctIdsByName = new TreeMap<>();
		Map<Lookup, Set<SourceCell>> cellsByLookup = new HashMap<>();
		Map<Lookup, String> ownerByLookup = new HashMap<>();
		for (String name : OptionalFanoutFixture.BINDINGS) {
			cellsByName.put(name, observation.sourceCells().get(name).size());
			distinctIdsByName.put(name,
					(int) observation.idsBySourceCell().get(name).values().stream().distinct().count());
			assertThat(observation.idsBySourceCell().get(name).keySet())
					.as("each observed source cell for %s has a stable ID", name)
					.containsExactlyInAnyOrderElementsOf(observation.sourceCells().get(name));
			for (Map.Entry<SourceCell, Long> entry : observation.idsBySourceCell().get(name).entrySet()) {
				Lookup lookup = new Lookup(entry.getValue(), observation.positionMasks().get(name));
				String previousOwner = ownerByLookup.putIfAbsent(lookup, name);
				assertThat(previousOwner == null || previousOwner.equals(name))
						.as("fixture columns must not share an ID/position lookup pair: %s and %s", previousOwner, name)
						.isTrue();
				cellsByLookup.computeIfAbsent(lookup, ignored -> new HashSet<>()).add(entry.getKey());
			}
		}
		Map<String, Long> coordinateCallsByName = new TreeMap<>();
		for (String name : OptionalFanoutFixture.BINDINGS) {
			coordinateCallsByName.put(name, (long) observation.sourceCells().get(name).size());
		}
		assertThat(coordinateCallsByName).containsExactlyInAnyOrderEntriesOf(Map.ofEntries(
				Map.entry("patient", 0L), Map.entry("measurement", 0L), Map.entry("reading", 0L),
				Map.entry("diagnosis", 3L), Map.entry("severity", 6L), Map.entry("drug", 4L),
				Map.entry("route", 8L), Map.entry("language", 16L), Map.entry("procedure", 3L),
				Map.entry("author", 2L), Map.entry("department", 2L), Map.entry("status", 2L)));
		long coordinateCalls = 0L;
		for (Map.Entry<Lookup, Set<SourceCell>> entry : cellsByLookup.entrySet()) {
			long sourceCells = entry.getValue().size();
			coordinateCalls += sourceCells;
			assertThat(observation.callsByIdAndMask().getOrDefault(entry.getKey(), 0L))
					.as("one source resolution per distinct producer cell for %s", entry.getKey())
					.isEqualTo(sourceCells);
		}
		assertThat(coordinateCalls).isEqualTo(46L);
		assertThat(observation.totalCalls() - coordinateCalls)
				.as("the three prefix values have no replay coordinates and resolve once each")
				.isEqualTo(3L);
		System.out.printf("OptionalFanout live-coordinate observation: tier=%s route=%s rows=%d coordinateMasks=%s "
				+ "cellsByName=%s distinctIdsByName=%s positionMasks=%s callsByIdAndMask=%s%n", tier,
				observation.route(), observation.rows(), observation.coordinateMaskCounts(), cellsByName,
				distinctIdsByName, observation.positionMasks(), observation.callsByIdAndMask());
		assertThat(cellsByName).containsExactlyInAnyOrderEntriesOf(Map.ofEntries(
				Map.entry("patient", 0), Map.entry("measurement", 0), Map.entry("reading", 0),
				Map.entry("diagnosis", 3), Map.entry("severity", 6), Map.entry("drug", 4),
				Map.entry("route", 8), Map.entry("language", 16), Map.entry("procedure", 3),
				Map.entry("author", 2), Map.entry("department", 2), Map.entry("status", 2)));
		assertThat(distinctIdsByName).containsExactlyInAnyOrderEntriesOf(Map.ofEntries(
				Map.entry("patient", 0), Map.entry("measurement", 0), Map.entry("reading", 0),
				Map.entry("diagnosis", 3), Map.entry("severity", 2), Map.entry("drug", 4),
				Map.entry("route", 8), Map.entry("language", 2), Map.entry("procedure", 3),
				Map.entry("author", 2), Map.entry("department", 2), Map.entry("status", 2)));
	}

	private NativeResultCoordinateObservation.Result observeActualProducerCoordinates(Tier tier) {
		var parsed = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null);
		var optimized = NativeResultCoordinateObservation.captureOptimizedExpression(tier.route, () -> {
			try (SailConnection connection = repository.getSail().getConnection();
					var results = connection.evaluate(parsed.getTupleExpr().clone(), null,
							EmptyBindingSet.getInstance(), false)) {
				while (results.hasNext()) {
					results.next();
				}
			} catch (Exception failure) {
				throw new IllegalStateException("could not capture the actual optimized IR expression", failure);
			}
		});
		return NativeResultCoordinateObservation.observe((LmdbStore) repository.getSail(), optimized, tier.route,
				OptionalFanoutFixture.BINDINGS);
	}

	private static Map<List<String>, Integer> expectedRows() {
		Map<List<String>, Integer> expected = new HashMap<>();
		String patient = OptionalFanoutFixture.NS + "patient1";
		String measurement = OptionalFanoutFixture.NS + "measurement1";
		String reading = OptionalFanoutFixture.NS + "reading1_1";
		for (int diagnosis = 1; diagnosis <= 3; diagnosis++) {
			for (int severity = 1; severity <= 2; severity++) {
				for (int drug = 1; drug <= 4; drug++) {
					for (int route = 1; route <= 2; route++) {
						for (int language = 1; language <= 2; language++) {
							for (int procedure = 1; procedure <= 3; procedure++) {
								for (int author = 1; author <= 2; author++) {
									for (int status = 1; status <= 2; status++) {
										List<String> row = List.of(patient, measurement, reading,
												OptionalFanoutFixture.NS + "diagnosis" + diagnosis,
												OptionalFanoutFixture.NS + "severity" + severity,
												OptionalFanoutFixture.NS + "drug" + drug,
												OptionalFanoutFixture.NS + "route" + drug + "_" + route,
												"language" + language,
												OptionalFanoutFixture.NS + "procedure" + procedure,
												OptionalFanoutFixture.NS + "author" + author,
												OptionalFanoutFixture.NS + "department" + author,
												OptionalFanoutFixture.NS + "status" + status);
										expected.merge(row, 1, Integer::sum);
									}
								}
							}
						}
					}
				}
			}
		}
		return expected;
	}

	private enum Tier {
		COMPILED(OptionalFanoutRouteAccess.compiledIrRoute()),
		INTERPRETED(OptionalFanoutRouteAccess.interpretedIrRoute());

		final String route;

		Tier(String route) {
			this.route = route;
		}
	}
